) AS (
  VALUES 
    (512::BIGINT, 'En lo personal no se me hizo mal profesor, pero es que tengo muy buenas bases en mate. Es una persona muy sincera y cae bastante bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, '511fcedf9c8df8723f7b3a7e1c4f59aa15be1401b51707ae4978c5376ddaca76'::TEXT, ARRAY[2439]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '133d46c7b25a71fed40687f013e7bdea013f5dde2b3f469e6af95bd4fc8e8438'::TEXT, ARRAY[2439]::BIGINT[]),
    (512::BIGINT, 'La verdad no es mal profesor, pero las primeras clases no me gustaron para nada, hablo y usó mucho la ia y en general siento que para mate eso no es útil, pero el mae cae bien. No volveria a matricular clases con el.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'ede1599dd956337f1afa8f9596ef3cd7c06c32885ec1b3111d30a2faa92900c8'::TEXT, ARRAY[2439]::BIGINT[]),
    (512::BIGINT, 'Llevé casi todas las mates con él. Es excelente profesor y persona. Abarca dudas y ayuda bastante si ve que uno se esfuerza.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'be9146793fd4ee2970d6e69b62815b3ad3aeaedc98e13e8884a92410ed193921'::TEXT, ARRAY[935]::BIGINT[]),
    (512::BIGINT, 'Las clases son aburridas y no da muchos ejemplos pero el porcentaje de quices y tareas se gana muy fácil, solo es ponerle en los exámenes y el curso se pasa fácil, ademas, tiene un asistente 10/10'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-29T00:00:00+00:00'::TIMESTAMPTZ, '14520994db31da0da1e2fca1acd3cdc276278b84a52e359847e30cba704600ee'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-05-16T00:00:00+00:00'::TIMESTAMPTZ, '84bb917f797f421d769dbdd20bd54e061025c7d71b15b2c104a6181b9b7cbb2e'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'si las clases se las da el asistente del mae mejor, ese mae explica muchisimo mejor que el profe y se adapta al estudiante. El profe explicando es mehh , pero el asistente es god tiene tips y toda la vara que te ayudan a pasar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-03-23T00:00:00+00:00'::TIMESTAMPTZ, '0d0faaefd1c0ab36b5ae028d6e7f8b9f7f62d77bf00987c4184febae5e85f879'::TEXT, ARRAY[935]::BIGINT[]),
    (512::BIGINT, 'Personalmente no me gusto nad, sus presentaciones son un desorden, sus clases demasiado cortas donde podría abarcar mucho de ese tiempo para realizar ejercicios, ponía al asistente a dar clases y varias clases lo que dejaba era la guías semanales porque le daba pereza dar sus clases, pero es pasable'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '95980103bc1185b19699d9b8d60640dbb3b7756f8cd2783b429fd72c1bcccc3f'::TEXT, ARRAY[935]::BIGINT[]),
    (512::BIGINT, 'Debería tener mejor puntaje, el profe explica súper bien, abarca la mayoría de temas y los quizzes y tareas súper fácil y prácticos. Vaya a clases y estudie y le aseguro que le va a ir bien. De la gente que nació para ser profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '095653e6af914ca4e1a4deb7936b7cff45d30dd597e51714ec2ec233df082f02'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Profe bien chill, matriculen sin miedo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'f1757af0aceab04983fc863e539c7adc6496643c6c3c2ca7d061e38c6fa1aff5'::TEXT, ARRAY[935]::BIGINT[]),
    (512::BIGINT, 'Es buen profe. El curso es bastante llevadero. Los exámenes sí son presenciales pero no son nada del otro mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1301c1df99667f40f073898aee63ed9046db0be56f63633895ba634c9712dfe8'::TEXT, ARRAY[935]::BIGINT[]),
    (512::BIGINT, 'El mejor profe sin duda, le recomiendo mucho matricular con el, califica suave y los quices las mayoría se pueden hacer en grupos y suelen ser ejercicios de exámenes pasados.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2025-01-27T00:00:00+00:00'::TIMESTAMPTZ, '037fc29f6f96aa520928b59c457ad9b01bba4f8986cae69b8aa782dff0446504'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Que buen profe, explica muy bien, se preocupa por que todos entiendan y se lleva muy bien con los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-12-19T00:00:00+00:00'::TIMESTAMPTZ, '21380e99469102cb8209d74a8f8b74eacedd78a68047655d52ad3344366b60d9'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Vi muchos malos comentarios sobre él, pero hubo uno que decía que ya no es lo que era, full razón, excelente profesor, si está repitiendo el curso llévelo con él, te va a ayudar, hace la clase amena y si asiste a clases le da puntos que le hagan falta. Desde mi parecer muy buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0d213fa83947c63e9e1f94ab26fe2e55de9815c056b3b9e7ecd1d27dd7404366'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Puede que en otros cursos sea bueno pero superior no es uno de ellos, a no ser que tenga la facilidad de estudiar por su cuenta no matricule con él. Lo único rescatable está en que califica suave y la gran mayoria de quices son grupales'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'd25621b6c9f1efbe01fe9d38df01309426438a09ad81353588672b942674cfd3'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'El profe es muy bueno, tiene una personalidad muy vacilona y hace que las clases no se hagan largas y aburridas, es muy buena gente si uno tiene dudas, califica suave y ayuda con trabajos para subir el porcentaje, sin embargo, es un poco confuso cuando explica, a veces no se le entiende.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'a9dc5073877deeee2e89859751f743e5c5d84db680b79b3271c35f59286cca38'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Excelente profe, explica abarcando todos los temas del curso, busca el aprendizaje de cada estudiante, califica muy suave y justo, sus trabajos extra ayudan mucho a subir porcentaje, si vas a consulta te ayuda y puede que eso ayude si te faltan un par de puntos. En verdad lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9d8e62f93740fa3a5bc56a58443419257352691b63ce132a2fee32de877eaf5d'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Los comentarios no se comparan a lo que hoy en día es el profesor, al inicio iba desmotivado pensando que seria como lo describen aquí, pero para nada, todo lo contrario, ha mejorado demasiado y es bastante atento, buena gente y buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8724f69aebb8d70f1c878e6896aa0c25082665a4269886020e70e624c17ccddf'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'El profe califica muy suave, y al final ayuda mucho con las evaluaciones, y es muy amable.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f2b86a5ca7c73bd46cd05a918b7cb1e45639dd0b570f9dc2ba9418ed848251b8'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Es un profe que ayuda mucho, califica apoyando al estudiante, los quices y tareas son bastantes fáciles. El problema es con los exámenes deja al estudiante poco preparado, clases cortas, ejemplos muy fáciles y esto perjudica en el examen. Esto se resuelve con tutoría.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5025701278ca3e2436f986cb92b7bdffbbe17e688cfa8be437dcc5e79194b900'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Horrible profesor, pésimo, no lo recomiendo en lo absoluto'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a3497df19d8237716124fec1d21e1810d3c28d9809017b737af969c13cd3eae6'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Para nada comparable a las reseñas que tiene, es muy amable y cómico, hace que la clase se sienta corta. Da mucha ayuda y le importa que uno aprenda, hay que ser autodidacta con una pequeña parte de la materia pero generalmente es la materia más fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7b63c4ada33ddc01ac558b64a716f2fc33137b43b76fe91cc8e195aaa425c3df'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'A veces se brinca uno que otro tema, y pierde el hilo en la clase, pero explica lo necesario, deja pocos trabajos y califica suave, muy buena persona y si necesitas ayuda seguro te la dará.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4209dcf5c2fdd27b5757c1d2230251badace59b14b71fd0792c48f41044daf7c'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Muy buen profe no es, no califica muy duro pero la mayor parte de la clase se la pasa hablando de fútbol o otros temas ajenos a la materia, se salta algunos temas, es bastante desordenado pero es muy buena persona y si vas a consulta te ayuda. Si matriculas con él asegúrate de ser muy autodidacta'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '85d2271418e390024a4af2ad355aaf22fad9ddfbcff318911526759d3fc70e20'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Excelente, no solo ayuda a los estudiantes a pasar la materia, pero las explicaciones NECESARIAS para las ingenierías son de muy destacables, se nota un gran interés en el aprendizaje del estudiante. Pudo haber hecho el curso muchísimo más complicado, por mucho. Volvería a matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '2df53db47524d681d16dc46075837887336402ca94a0fe1e7f9b4d39e0a5ff98'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Es un buen profesor, la verdad ayudó bastante para que uno pase el curso, hay que ponerle porque hay temas complicados pero la clave es no faltar y llevar la materia al día, las reseñas que tiene no me parecieron nada a como es el profe, en realidad me gustó llevar ese curso con el.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '712f939460cdbb5c1fcc37068b5620b4f79828b76a8cb4054f4bb7274e9e146e'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'El profe es buena gente, tiende a aprovechar el uso de las clases virtuales cosa que no está del todo mal pero cuando es el final del semestre se abusa con eso, contesta consultas virtuales que no es malo la verdad bastante bueno. De lo unico que mas me quejo es que el hace ejercicios muy fáciles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'aaad7f45281fcef8f91d2a48a3ceb8beca35298bedfc6625639436e8875f8448'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Muy mal profe. Un 80% de las clases las hizo asincrónicas. Pésimo para contestar consultas y reclamos, puede durar hasta 5 días sin responder, y si es que responde. Para lograr pasar el curso debe ser muy autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, '7c717d904846669b9947d8f6e0cb0eda77a1c213cf25c52a6e01849b8a2ac69b'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Buen profe, solo tener cuidado cuando el mae se le mete por hacer muchas clases virtuales como a final de semestre, ya que cuando llega ese momento el mae o hace la clase o deja alguna actividad de la cual no creo que aprenda mucho, entonces le va a tocar aprender por cuenta propia.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '57bd6de42dd67c79f35af5e78d11b72cf311cc3f247e2c7251e62d807d3aa98c'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Es un excelente profe, explica de forma clara y repite las veces que sean necesarias para que el grupo entienda la materia, nunca se desvía del tema y se nota que sabe bastante del curso. El profe ha cambiado mucho con respecto a las reseñas que hay de él, lo considero buen profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a886750e4597fd7cda79129a597c40085bf216de063c16be810b3d2d93f46b91'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Tenia bajas expectativas por las reseñas que leí pero la verdad me sorprendió. Nunca tomó las 2 o 3 horas de clase completas y aun así le daba d]chance de ver la materia y le sobraba tiempo para hacer practica En consulta es una teja y se preocupa bastantes por que uno entienda la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2023-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'd5e148615625e11e64ceb230c8fbb348f53b96283011390f0d85a73c8bf7b406'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'El mejor profe de CDI que llevé, iba desmotivado por los malos comentarios de esta pagina pero me lleve una impresión totalmente diferente. Muy pura vida y le gusta vacilar, explica bien y se preocupa bastante por que quede claro. Llevaria de nuevo con el sin dudarlo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '17ed766795e47c0dd9b84d7804733aab8a45e157e7719c012bc10b4ba44e907a'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'El profe es super buena nota. Si vos vas a cosulta él te va a ayudar 100%. Además que si mostrás interés él te va a reconocer y te va a ayudar un poco si lo necesitas. Explica bastante claro, y los quices no son tan rudos'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '82189cba8d8be97d219009b9020dcdd22d4ef65962f1dba398914beaaa7e90ba'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Este profesor encontró esta pagina (llena de malos comentarios, incluso uno es mio) y tuvo el tiempo de leerla. Eso hizo que mejorara. Cambió la opinión que teníamos sobre el y por lo menos este semestre fue buen profesor, espero siga así y no vuelva a ser el mismo mediocre de antes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b65e3171f5b9701a269d0c6b2eae8d322eb753b773ad5cd320c3d3982f8f1dd2'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Explica de forma concisa, el profe pregunta como les gustaría que fuera la metodología en clase, los quieces son meh, califica suave siempre y cuando sean bastante ordenados y no se brinquen ciertas cosas, clases cortas, brinda mucha ayuda sea en consulta como en clase, es buena nota'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '54c8f39c518b1fe476fa09a909b5e3f0a8d0f434218bfe82a1f1ff9e159d1cb8'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'La materia no deja de ser complicada, pero el profe ayuda bastante, me encantaría volver a llevar clases con él'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, '236e019525fb2825e7a5432e921d68d5206f9c08c20c01f9deb580a4ab3d8896'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'El mae explica rápido pero bien, eso sí de 3 horas se clases sólo dará a lo mucho 2, es suave con las tareas y quiz por lo general se le entiende eso si una que otra vez se salta uno que otro tema. Deja espacios para práctica cuando hay examen todo bien'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'd67e6b964ae0fd0943ea59471f4fca3f22400f4cac9506d4de9b57561f7a51ea'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'No entiendo porqué tiene mala calificación, puede haber mejorado como cualquier persona. Llevé este semestre con él y fue excelente, explica súper bien, se preocupa de que los estudiantes entiendan, es empático con las tareas, en consulta ayuda un montón, es tuanis. Sin duda lo escogería de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ba3239c14d06e260ae454cff5afb454639902f5247d82ff58ba6a40ed148d3cb'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Este profe no vale la pena en ningún curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bbad72a085b2fceae163af10ab865c4321c5e1092f8ae1b6bb164171fea29117'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'No responde mensajes, habla de cualquier cosa excepto de la clase, tomen un tutor para la materia porque con él NO SE APRENDE NADA, con costo explica, y para responder mensajes urgentes ni en sueños. Prefiero perder la materia en vez de volver a tomar el curso con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4a4d1638b177cfac8cf7bbbdb6bb2e36c450aa5fec9db4286e003e8d859d93ce'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Un profesor que nunca da clases, nunca responde y califica hasta después de semana colchón. No le importa el aprendizaje de sus estudiantes y lo único que le interesa de la clase es terminarla rápido y hablar de otros temas ajenos a la clase como fútbol y política.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6922c9c921b3f0b326c41b07127e18f6c512006e5db8224ddc87538773b18407'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Mal profe, no da la clase. Cuando llega a dar la clase no explica bien, explica solo 1 parte de los temas semanales, generalmente la mas sencilla. Dejando de lado las partes importantes. Las clases son mas cortas de lo debido, se nota que ni el entiende la materia.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f748401c6ed9bacd5cb23863f61df6ad1d49b89e58e4618ce67895914ebe2c48'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2022-05-22T00:00:00+00:00'::TIMESTAMPTZ, '6a8049d7102249dcaceec4f87dd2ad7a0ecfd2dd86e55f0465e6626d3e7f36af'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-29T00:00:00+00:00'::TIMESTAMPTZ, 'e3e05657dc5ca4149cd7249ef6a7996b3ad3dd4dfe9203abde8ad0e2de5dfc63'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Una cag*da de profesor, nunca ayuda, nunca está, siempre tiene problemas para conectarse (lo peor es que ni se esfuerza en mentir bien). Meter con este mae es básicamente para no tener profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-10T00:00:00+00:00'::TIMESTAMPTZ, '242b3e8c337900f6620aefa5da43ac126380d85813dbefc43ea0bed9b24fc257'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Me cago en la hora que matriculé con este playo. Inexistente, las clases son un insulto para los estudiantes del TEC.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, '46f22520699d18cf411859854904d4f70693b31fed5dc2835c37923e3782cb99'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Sus clases son muy desordenadas. Él se presenta como profe a disposición y nunca está, cuesta mucho que responda a consulta. No recomiendo matricular con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dc0905069360e227d0e600eebf1115cfbedf5c36078db1282b03dcb2e01498fd'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'No sé que hace este compa durante el día, cosas del curso lo dudo mucho, pero pasa "ocupado" todo el día y nunca ayuda a sus estudiantes a resolver ejercicios o aclarar dudas. Se presenta como un mae pura vida pero en el curso se desaparece por completo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3639a0f2f5523f4ca315a91fb1fc66b7e77ff8a0a5e1a6beaefd9a77bc02b68f'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'No creo que en todo el TEC exista un profesor peor que este mae, me atrevo a decir que sin profesor nos iría mejor. Si mete con él, vaya a tutorias o asista a la clase de algún otro profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'a43ea311c7c8cdcf5c8cb812817c30560a584fabe670d60320a51d4d30793514'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Perdí la beca gracias a meter con este malparido. Un profesor inexistente, los quices los da a final de semestre cómo "nota general", la materia que da es los ejercicios más básicos, en pocas palabras ud jamás va a estar preparado para un examen del tec.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-04-04T00:00:00+00:00'::TIMESTAMPTZ, 'cbda195e1aed802e5346dd2781fb659f082c0e181355d05421e8b9a7515a476b'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Mae ni pierda su tiempo yendo a clases o preguntandole una duda, este mae es el ser más inútil del mundo. Se está robando el salario básicamente.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'd6432389cd7231de035966e940e1a6596d6a660069aca2ecf9ddcb6f882c8db2'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Es en realidad un gran profe si su materia fuera la legalizacion de la esclavitud en el siglo 21, jueputa profe mas mamapichas en serio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-17T00:00:00+00:00'::TIMESTAMPTZ, '3bad0ad43ba3f0073e2afc2e7d83ce9431d2bb58941b5cd75db553a33f45ca82'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Que mae más irresponsable, cómo trabaja en el tec? No da el material para poder abarcar la materia, no apoya, no nada, da la materia de la forma más básica posible con conceptos que quedan en el aire y al final son importantes, yo calculo que nos hubiera ido mejor sin profesor pero con un temario'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '22a3d5d02e5ce9b6f4221a777cec5f4d9730019ade5d61fb8321333b3d7f9f4b'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'No es recomendado para Superior: no está interesado en lo más mínimo en dar la clase, menos brindar apoyo si hay alguna duda que sea fuera de la clase. Califica a último momento y muy apresuradamente, puede dar las notas de quices hasta semana colchón. Hay que rogar por una corrección de nota.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'bb3926c2660740c20a8cff8a28792eb49f940f5f11d23efe50db83a615d58c1c'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Realmente es un profesor muy vago, en mi caso nunca llevo al dia las revisiones de los quices, solamente daba las notas por la presion que se le ejercia en clase. Es muy desordenado y te toca estudiar por tu cuenta. No vale la pena llevar un curso con este profesor.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-01-23T00:00:00+00:00'::TIMESTAMPTZ, '54e281b24c62900ad4079c9cc5d0d7a10161b5084c949ff7a84e62226c2f13da'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Este profe se muestra como una persona que podría ayudarlo a uno, pero al momento de pedir ayuda, se le debe rogar si es que la da. Además, siempre presenta los ejercicios más simples, y se enreda al explicar.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, '5315648ffc2a1a23f7dfdf0a19c099fd061f9c021c7172010d7f605e16a4ef9b'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Este profe no funciona como tal, si hay alguna mejor opción pues hagale'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, 'cda6e0acccb000d423d3871543d973e371a16f83a01c9323e70afd7240ff0619'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Mejor atrasarse en la carrera que llevar con semejante inepto. Resuelve dos ejercicios facilisimo a y ya, eso es dar la materia para ese incompetente.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-10T00:00:00+00:00'::TIMESTAMPTZ, '2065093ea6d24d52ab55fbcf73d4fb1998bd4572434c0b464f99b7ecb1a33ce4'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'El TEC es reconocido por sus profes malos y este mae está entre el top 3. Inepto'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2020-10-14T00:00:00+00:00'::TIMESTAMPTZ, '88e3aab09deefc7b5d9a8257042d9386cfde3b6f1a823b266f8f6d021c216eb7'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (512::BIGINT, 'Inútil. En esa palabra se resume este pseudo-profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-10-02T00:00:00+00:00'::TIMESTAMPTZ, '924c1a13c22ec31757ba5085b5c04664e0911d5e38f95a727ffc4977d7d55e65'::TEXT, ARRAY[1034]::BIGINT[]),
    (512::BIGINT, 'Yo he tenido profesores malos, pero este mae se lleva el premio gordo. Irresponsable, inútil, da sueño, no ayuda, nunca disponible, no hace nada en clase, ejemplos super simples, etc. Todo lo malo que ud se imagine en un profesor él lo tiene.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-09-23T00:00:00+00:00'::TIMESTAMPTZ, '33668ca9ac2d3e9a1d79ea8946e4448e9e73453862bd32c47dfaa23c1aa0be80'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Hágase un favor y no meta con este inútil. Profesor que lo único que sabe es leerle a uno los problemas ya resueltos de los pdfs, fuera de ahí, no sirve para ni mi***. Jamás espere que el mae lo ayude o le conteste un correo/texto para una duda, solo le cuadra llegar, leer y desentenderse del curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-09-10T00:00:00+00:00'::TIMESTAMPTZ, '82e942fc55bec218188c9d1c10ea9cd40d16b19e8c0725dc660c35e00fe5f92a'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Si usted busca "BASURA" en el diccionario, le sale una foto de este mae. Es complamente incompetente, en la segunda clase gastó una hora solo para hablar basura de su vida privada. Espero que lo despidan, no merece trabajar ahí. Nos insultan como estudiantes con maes como este PAYASO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'e68f6be702f2168c4c96f45e42128a1bf64fb04a4b52c77d97b60045aee71439'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Pésimo, la única razón por la que pasé fue porque pagué un tutor a medio semestre ya que este "profesor" de resolver los ejercicios que ya estaban resueltos en el pdf no pasó. Cómo dicen otros comentarios, mejor no pierda la plata de la matricula metiendo con este inútil.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura']::TEXT[], '2020-09-07T00:00:00+00:00'::TIMESTAMPTZ, 'd3f420e032ae8ed51c30c6ef64d5dfbada58faad1899881862a2d84310b239cc'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Este mae sin pelos en la lengua es una basura de profesor. Yo había matriculado con Otro profesor que si tiene alta calidad, y me cambiaron la matricula con este pana porque YOLO. Si les pasa esto, quiten su matricula, este mae no merece pero ni su barro en el zapato'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '5dc84265a4ba0d5d2ede10223fe02d519121caea0f31e848c0995a0cbeafc64e'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Sus clases se van entre explicar los ejercicios más obvios y contar datos irrelevantes al curso, jamás nos dejó una práctica ÚTIL y nunca se dignó a ayudar al estudiante en hora de consulta o al menos a mí no. Si es su única opción es mejor atrasarse que perder la plata de la matrícula.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2020-08-31T00:00:00+00:00'::TIMESTAMPTZ, '5b8ef50081938b16607b85f365d1b3c7089fdb74295bbb6432b820643051f5a4'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Un profesor completamente mediocre, le interesa muy poco el estudiante, en modalidad virtual nunca ayudó a resolver ningún ejercicio, todos los msjs en visto.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Clases largas']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '159935d1bbdeda4fc8c0c760af5b3640f8cb88cdc942141cf9bb72c8026ad4ad'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Con la modalidad virtual este profesor llevó la vagancia a otro nivel, cómo desde semana 9 empezó a dejar de dar clases (él lo decidió y ni preguntó) y empezó a enviarnos videos solucionando lo que ya venía solucionado y explicado en los pdfs. Es un vago, cómo no tener profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'e4cdcafdcc8103a4517f7cdb2d84cae0b99d6e916a12100a2fdd51b6940b6544'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (512::BIGINT, 'Vago, le da pereza profundizar en los temas, de esos profesores que creen que un ejemplo fácil ya es suficiente. Cualquier excusa para no dar la clase él la usa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'def90431185be80d3b87d698d94ea648389e9c9071f191b25224ee126e814f6a'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'No ayuda al estudiante en lo más mínimo, él solo llega, reparte pdfs y jueguesela. Me tocó ir a hora de consulta con otros profesores y meterme a otra clase porque con Melvin la única forma de pasar es que ya haya llevado el curso unas 3 veces y tenga material de otros profes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '19a9cfba40a2ac9a3ef57d599fa40647d68d9b2a094717a1fc9dc354380f2cde'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Yo me pregunto con qué cara cobra el salario este mae? Aparte de llegar a "dar clases" (leer pdfs) no hace otra cosa, no ayuda, no da una práctica, habla cómo con sueño y sólo chistes tontos de cervezas sabe hacer. Hay que rogarle para que suba notas, uno no sabe si va bien o mal hasta el puro final'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Exámenes retadores']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'fb136c250efa5c7a60ea7bd3c0546db6a67dc6cd9dac40b6444c661ec73b8cbe'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Yo llevé el curso varias veces y solo por eso logré pasar el curso porque con él no se puede. Tuve muchos problemas con el respecto a las notas y que no me contestaba los correos. NO MATRICULEN CON ÉL.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'fced22057e59ac090e725b9f1c83b6504b363226bc0d28f1984e76733a405dd2'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'En mis años de TEC no había tenido un profesor tan poco profesional. Da la materia cómo por encima, se salta subtemas, no da recomendaciones, no da prácticas útiles (puras varas fáciles para que ud crea que está aprendiendo) pasa hasta una semana desaparecido con cuentos de que tiene algún problema.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'f57396f1d5b76c189f9cc6fc20bc9bb1f7f710f29097af4de110e5677faf5fe8'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Un horror... de esos profes que piensan que "cayendo bien" y no jodiendo lo ayudan a uno. Los cursos de mate necesitan mucha práctica, cosa que este "profesor" jamás dio. Pasó enseñando los ejemplos más básicos. Deberían mandarlo a dar clases a la Latina.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '9e1be15f7b3284963e9bf94bfa868456e643599845f697a6f94dbd20dfea4c02'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'No metan con este mae a menos que sea la única opción. Nunca estuvo a la hora de consulta, le envié varios msjs con preguntas que no podía resolver para ver si me ayudaba o me guiaba y nunca respondió, claro, llegaron los exámenes y me sonaron. El mae no sirve ni para una consulta pequeña.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '7f9ae74c27e3de60a75781d70f881d655576428723a187fec9cc46d0dd28f8f9'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Desobligado, le molesta que uno le pregunte y si le pregunta más de una vez prepárese para la cara que le va a hacer. A todo lo anterior súmele que a partir de semana 14 ud deja de tener profesor porque el mae empieza a sacar excusas baratas para no dar clases. No entiendo cómo trabaja en el tec.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, '99e7dd352e46594d15dc508fd39f9f95f185767836014e9ae2fda606cb57ab81'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Por cuestiones de horario ya he llevado 2 cursos (por desgracia) con este mae y los dos cursos los perdí por la misma razón, es un irresponsable, nunca da la materia completa, dá lo más básico/fácil para salir del paso y robarse el salario. Increíble que el TEC contrate a un incompetente cómo este.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'b4c4f22d9a9c9965713745d747d686eb36d7ab1c3e4be8e2c281b05d43192518'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Prefiero matricular en la sede de Limón o atrasarme en la carrera antes que llevar con él otra vez. Nunca responde una duda, la hora de consulta nunca está y ni sueñe con hacer un reclamo del exámen. A eso súmele que en clases poco le falta para que veamos solo sumas y restas. Llega al examen y tome'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'cfc63cb86cec47def0e31cf3c2d206f4078b610ec98b6d6ed50a1e8017a92747'::TEXT, ARRAY[1049]::BIGINT[]),
    (512::BIGINT, 'Cómo es posible que alguien tan irresponsable sea profesor? Nunca dio nada útil para el examen, básicamente se guindaba de los pdf''s (que no fue él quien los hizo) para leer problemas y hacer lo mismo que estaba en el pdf, ud le consulta y da una explicación tonta así cómo para que no pregunte más.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas']::TEXT[], '2020-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd67e41131afdd44357573f00d10b7809012c255b7402fc0e166505f4feeb3455'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (512::BIGINT, 'Si me pusieran a elegir entre que me de clases este "profesor" y me de clases uno de los perritos del TEC prefiero al perrito. 0 comprensión al estudiante, 0 interés en dar clases, 0 responsabilidad. Estas son las horas donde sigo esperando saber porque tengo un 13/20 en los quices ya que no los dio'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-05-27T00:00:00+00:00'::TIMESTAMPTZ, '4fe021084bcda4fbebbcbe06a715046cc71cf6d3c5df8d385d00bd819460b3bd'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Pésimo, parece que le da pereza dar clases, hace 2 ejemplos de un tema, medio explica los pasos y listo, luego en el examen vienen problemas más complicados que ocupan soluciones más especificas y eso él no lo enseña... Llevelo con él sólo si no es por primera vez y es autodidacta...'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2019-12-12T00:00:00+00:00'::TIMESTAMPTZ, '6ec65a7370ee87af005a1841e0f7d5aaf033477e89a57f9341ceded68e6bcb59'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f3c76fd0af4fd9eb5623289fe3aab56688cf580910ef516254b469bfbf0f3b93'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Es buen profesor, pero los ejemplos que da en clase no se parecen nada a los ejemplos que podrían salir en los examenes. Los quices son algo difíciles y tarda mil años en entregar las notas finales. Intenten salir bien en los primeros 2 exámenes porque para el 3 es súper desordenado'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'acabeb4f7540b5b7e93715c89e996ee4dd7893ebbdadfdf5b1198a120df9ce5b'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Es claro y hace que te llame la atención lo que explica porque suele contar historias de la gente que admira en la matemática. Debes de ser interesado en aprender porque ya el curso por si solo es difícil, explica como se debe solo que no da trucos.Es un muy buen profe y no comprendo su calificación'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, '84d2d6c6903b2a8196670909a6cb5eaf2529a2e411c52c247eaee1c50a5ccc79'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Honestamente no entiendo la mala calificación. Sus clases son excelentes, hace las demostraciones demasiado interesantes, es imposible dormirse porque siempre llevas el hilo de la clase. Hace mucha práctica de exámen y realmente se preocupa por que pasemos los exámenes y que aprendamos matemática.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'adeac98f691ba8d8861c97faab30abb85c10318dfa109126c9a9e70e7c92df0d'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Si ud es repitente y siente que puede pasar cálculo sin ayuda de un profesor adelante matricule con este, pero si es su primera vez o siente que necesita evacuar muchas dudas ni lo sueñe, nunca está disponible, jamás responde un correo, en clases explica bien porque explica lo más simple...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '8d786b8bb523e0f8493004cb4e723018bca961608491c3c78a2653f6824dbc3b'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ea78f4f4597a1e837b216eb9a87468481e1a85fc143348e9e1d9f817b76824d9'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Pocos quices y tareas, dura mucho para revisar los exámenes pero explica bien y genera un buen ambiente'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2b122efcd252679eaf4b6ad507f91fb44867f24f32b7b075603bd7d1c17c1faf'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Háganse un favor y no lleven el curso con él. Es terrible explicando. Para pasar hay que ser 100% autodidacta. Jamás lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd889b7e54f8a9c048142ef554687b23cf1d73f0d97360380056770b47a681b89'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e46bd0fa7b3656ccec5366b4d3b737c673e407264150d0dd5b16b02d18276936'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Pésimo, en clase resuelve los problemas más básicos y en el examen todo es diferente, entrega los exámenes 3 semanas después y los quices ni siquiera los entrega, al final sólo nos dio la calificación general de estos y el tercer examen no lo entregó, sólo subió la nota al Tec Digital y listo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'dae93abbc7df78e94faf0b7bd1541f56ec38439bc7fede2e98a34b34e60182f2'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'El profe no es malo, es muy teórico y hace pocos ejemplos, sabe mucho pero es sumamente irresponsable, entrega los exámenes como 3 semanas después, y se lleva tramados a los estudiantes con excusas pobres, también falta a clases a veces con las mismas excusas. Si pueden evitarlo es lo ideal.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '56d93ed7d1b26717034f4ab289d9d10c6edefc3cff2193ab59272e7846a0e4da'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Sabe demasiado de matemáticas, como profe no es el mejor, pero es una buena opción, repace y practique mucho en casa y le ira bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '11bd4858f7e06bb0f250e743a75d90072ed5998e487708916ecc26e3564b5ab7'::TEXT, ARRAY[2439]::BIGINT[]),
    (512::BIGINT, 'Sabe mucho y califica bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'c6914f6113aee6da64507e9e9b5833069df507af5497c1f4a5e9330bc6b81972'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Explica muy bien y aclara todas las dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-12T00:00:00+00:00'::TIMESTAMPTZ, '0b14b899df3301f961b573949c4dfa048abb17a61060884e017d38c5d2c813c6'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Imposible perder un curso con este profesor, decide hacer los quizes dificiles para estar mejor preparado para los examenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '18709c83a9f3c3c6efe4fe83ad9fe80a682d3b74452e0001e2c9ba478d2d41dc'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Quices y tareas difíciles, y escribe mucho. Para el último examen es muy desordenado. Califica justo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '198803fb1428b9dacee5afeea191b3c13c60c60de7d08a55e7c37435f9e44317'::TEXT, ARRAY[923]::BIGINT[]),
    (512::BIGINT, 'Demasiada teoría, un ejemplo por tema, nada de prácticas. Además es demasiado desordenado, pierde quices y tareas, y las entrega al final del semestre. Nunca entregó el último examen ni las notas, sólo las subió al sistema el último día.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '89ac221a5b60c61c4318061d8524794eb0bba0ed7c0f1ff40dcc82e3daf119c3'::TEXT, ARRAY[1018]::BIGINT[]),
    (512::BIGINT, 'Explica bien pero da pocos ejemplos, dura para entregar las cosas y dice que va a hacer algo y un dura mucho para hacerlo o no lo hace, pero el profe es pura vida.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '6693f16fc68ed7581039f072797a295f997382ac218f014c9fb80594128090c7'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Se interesa porque los estudiantes entiendan, da poco ejemplos pero suficientes para el aprendizaje.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-04T00:00:00+00:00'::TIMESTAMPTZ, '91318de71f1f1b58f3ddfb6e5cfe7fdd05dc1b1ddea324a3bb4fc2f9a8c5ee77'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Si hay otro profe meta con el otro, todos los quices y tareas las deja para final de semestre. Es desordenado, da muy pocos ejemplos en clase y si necesita consulta mejor busque a otro profesor en la consulta no explica nada y siempre está con pereza o hablando con otros profesores.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Pocos exámenes']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '8ac2ac8b1de466c343690d98df99b93fe6d297a5cb6dcbf659b7c1974f84cc09'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'En clase trata de que todos entiendan, sin embargo es demasiado perezoso, dice que va subir exámenes resueltos y los sube un día antes del exámen, nunca cumple su palabra en cuanto a eso. En consulta es demasiado desinteresado siempre tiene sueño. Si es lo único que puede agarrar meta, pero hay mejo'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, '18efe2c390811b6e7738b3f94257fa78d6c0f9efc5ee6929f898b5f6de0e1746'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Es un profe muy tuanis, se sabe muy bien la materia.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2017-10-09T00:00:00+00:00'::TIMESTAMPTZ, '8bd2f39f1868cf1ed2da62eab5497dda1792b09ebcee021f9cd574e83f047ba1'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Es buen profe. Toda la materia del cuaderno entra. Da pocos ejemplos eso si (1 ejemplo y a veces 2) pero con comprar los folletos de ejercicios de la librería se cubre ese aspecto. Por lo demás clases no aburridas, a veces no llega a la solución pero la siguiente clase da la solución'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '48f7a3ebe963e1b2211c8fe5d9f49c8ed37dd8b51762d25755f1423729214cd8'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Explica demasiado bien, hace pocos quices demasiados difíciles, pero son muy parecidos al examen. Hay que ponerle mucha atención porque va muy rápido y es fácil perder el hilo de la clase'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b678144a25d6905edd70b591075539783550710b49e7a3fa9c8b20ac87e4e0f1'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'No es bueno explicando'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'cc470945f48f2a174a738deb4480d6afe2740b7790d6763713def691d8e9899a'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'El peor profesor que he tenido, a pesar de que pase el curso es la peor opción, muy irresponsable como profesor'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5d224d878dc7757c6ecf732a1ffc30db1dfdcaf473a4358b70fb5f7cc2089a22'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '595f494d6f5f617ad1fdd4d432f35a75ac218c117140f1cbd35b44011a38b0a6'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'es muy bueno explicando, pero esta un poco despistado, a veces no explica toda la materia y mas bien explica temas que ni están en el programa. y espera que te pasas en consulta'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ff889d716a23161ba55d588fc4865a7a3592638f648f86636363fdd907a35fe9'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Explica muy bien, aprecia mucho que el estudiante se interese por el curso. Los quices son complicados pero en el examen se vuela por que es mas facil que los quices.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6d195910cf06e8612d67be7a26af4f0f23375b9937dc968a60a2845b4027c172'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Explica muy bien cuando tiene tiempo, a veces solo llega a leer del folleto y puede omitir algunos temas. Los quices son complicados pero pasables si se estudia.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'f4ff1ddd1edb7bccc2beff02458ca0d03770a1d4e75c253704481be81f84811e'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Es muy buen profesor, solo que el horario, no es para cualquier persona'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '25b84c2632a0f561d9823ef1712348a0e1accec7bc7536000bd53605fc27d319'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Buen profesor, explica claro y resuelve las dudas de los estudiantes sin ningún problema. Para los quices si hay que tener bastante dominio de la materia, sin embargo ayudan bastante para los exámenes de cátedra.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-21T00:00:00+00:00'::TIMESTAMPTZ, '8b0c7f7253a886acca72f8084cc04b8e7155e80312b54d406348f7c543bac1df'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Niego los comentarios negativos, al menos para algebra. Explica super bien la materia, se le entiende absolutamente todo, quices con dificultad normal(es el TEC no la U Latina), califica lo normal, como debe ser. Es muy puntual y explica paso a paso, si no se entiende s ele pregunta y el responde.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-13T00:00:00+00:00'::TIMESTAMPTZ, 'ab3c3b885bb259423fc95c3bf9635b77a9457798c2218ff9ee2ccdc41c259fda'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Todo es muy difícil con él, los quices son quebradores, califica un poco duro, pero al final del semestre si uno le puso, él puede que le ayude un poquito.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b7d8b12e382fe0fd4aa4679b0be8aa4a40c054cf46cdaec22b16685719752c90'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Demasiado parcial con ciertas estudiantes ... arrogance y pesimo!'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5049e96497b774d73b9398c2efd821d06868040d3a61b2460c63ffdaa2bd027f'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'De los peores profesores con los que he matriculado. Tiene preferencias entre los estudiantes, especialmente con las mujeres guapas. Se queda muy corto con los ejercicios y lo que llega a dar a clases lo copia de un folleto. Si no hay de otra y matricula con él estudie por su cuenta o de otra fuente'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '290032e2d1e7c7da48b44ed37b8d75c93258dc0a270b7211543aad3d3f246175'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Muy "crecido". Explica lo del folleto, no es la peor opción, pero hay mejores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f2ff8c6676a9b99e45f6268f8655a4d36938dc5cc9e30e67e0050cf078e3a620'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Es demasiado imparcial, si usted es mujer y "guapa" fijo pasa aunque no se lo merezca. No llega preparado a dar la clase y copia todo lo del libro de Paez, los quices son difíciles y pierde demasiadas clases. Todo lo que no se ve en la clase sale en el examen, es mejor estudiar solo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1c2d162aeec60ea51fb5b97012f703e174df60dd649d9e66f6636ce56d4a656f'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'No explica no bien ni mal, si se le presta mucha atención se entiende toda la materia. Es bastante organizado. Sus quices son un poco difíciles pero si le pone se pasa fácil.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ff5af7413335934ded1e59b54b4cd12d22421aa427f633bdde26c801ae40a8e4'::TEXT, ARRAY[1041]::BIGINT[]),
    (512::BIGINT, 'Explica lo que esta en el libro, y no muestra mucho dominio en el tema, sin embargo como persona es pura vida'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-10T00:00:00+00:00'::TIMESTAMPTZ, '32320a7edd6e91441b5ae6680c86289a71f0974f156b1afdc9edb56fd8659dd4'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Me parece muy buena persona, se preocupa por los estudiantes y no es el mejor explicando, por lo que requiere cierto esfuerzo de uno, pero si es pasable con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '665d943da97d8b7f02efec355edf3cf2ab1b78a3be0905d022aaccb3a9ba1c78'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Lo peor de la vida'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9c6c0cacd31a97b0f5d7ee1608c51ae2e03189b8524b76f85cae13db77098706'::TEXT, ARRAY[634]::BIGINT[]),
    (512::BIGINT, 'Es un poco serio, muy puntual y directo, sin embargo con el tiempo se "suaviza" un poco y uno se da cuenta que es muy buena persona. Sus clases son muy estructuradas, lo que a mí me gustó. Explica todo muy claro. Además le importa el estudiante. Hasta me dio su # de teléfono para aclaraciones.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, '8402664df73294b967c6ceb0ec9c90c9032b364be1c88f54288ad3076fb49e9a'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'b18547a26e88992665adb5380d6d8ccdf5afa76aef2b0252a8451bde6828d199'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-31T00:00:00+00:00'::TIMESTAMPTZ, '15736298ac0d13310f2d363359462137258224aab741d9589d862a1b2ab8fa93'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (512::BIGINT, 'Explica las veces que tiene que explicar si no entiendes. La clase no se hace aburrida y califica normal ni muy suave ni muy rudo. Es buena gente y te ayuda bastante'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'c4b57caa809999e4ca8d3e93ba3d2cb15a62a4c7d9a82a95499a81a89b826486'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Él es un poco engreído, sin embargo a mi me gustó mucho la forma en que dio el curso, para aquellos que ya llevaban materia al día era fácil; pero para aquellos que ocupaban un poco más de énfasis en esta materia no es muy bueno, ya que asume muchas cosas que no todos lograron entender antes'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, '2405ebf5ff3d52c08784b08a8a85a281619b211f1ce919124dac99a52fbd0bc6'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, '430b3cda1a77797466efc39f4e127315ce9de7950497143ad986db5c6b54a8f7'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'como ya mencionan el mae asume que uno sabe todo y hace unos enredos en la pizarra que ni el los entiende'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'af79c58dec5e81e6c886052a1b21f7a97c7f3a2e7810d06ea80b727f4abada71'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Asume muchos conocimientos como conocidos, por lo que no es buen profe. Si se lleva la materia al día se pasa pero el profe no es muy buena gente que digamos. Las clases son un poco aburridas y como dicen arriba, el mae es un presumido.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, '671ced6a7825302b6baed6cb0d2c88be3abc5615e741d654ceeac3a6ae9e0a9f'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '7facec7e6c15e8a0ac1551844660e7369c191aeb92e94204248c76d63f52b7d0'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'cf1583ddb9b34f3a2232419b0b422db0081d46f32cd203c8f29576fa390399bf'::TEXT, ARRAY[1018, 2439, 563]::BIGINT[]),
    (512::BIGINT, 'Por estar de presumido, no da sus clases con calidad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a1ad62a0b21a6dfbdb7fc9fda8dd33bf27caf565743681b3efc7c620a918fd78'::TEXT, ARRAY[2439, 1018, 563]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'dc8e5ba41ae34f4129699949789ae7fbd4846f6338bf8fd9d667a908d28c6d37'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Es bueno pero no es tan facil!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b6ffe53c2bb69ebaa1cf59d158ecb9f2dba3df9431d6e69efe67c0540bf685db'::TEXT, ARRAY[1034]::BIGINT[]),
    (512::BIGINT, 'Explica muy bien y siempre está dispuesto a aclarar dudas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f189776504a6ffc304d5015addb4b41f1de8094add583f4201819296edb51935'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'Un crack! Tiene salidas vacilonas pero es muy serio y dedicado. Explica desde lo más simple y no avanza hasta que se comprenda. Revisa accesible, no es un rata. Pero tampoco le va a regalar más de 1 pts para pasar. Con Melvin se aprende y se entienden bien las cosas, pero hay que estudiar, obvio!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7c8c76892b9ba8daa29710c667d44189c5eedd37de4c9175b1f60a7a00955f43'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'El man es buena nota, quices difíciles pero el man prepara muy bien para los examenes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'e03b61f0d352e1a53468f5cf3da02ab2e3b55ac805fcb93b011685582528b9ac'::TEXT, ARRAY[605]::BIGINT[]),
    (512::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '82468e1ff36f905a78c232be34fee453bfa57092e0f5e04e258f4b4decd75061'::TEXT, ARRAY[563]::BIGINT[]),
    (512::BIGINT, 'explica muy bien, hace los quiz dificiles, pero eso ayuda bastante en los examenes.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'bf2bd9f36d9d5d7def3f4a0ea0e7b0530eaa14c694f887134b8d5f09460b7b49'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
